from authoring_helpers import DraftBatch,formula
b=DraftBatch('W01-L03-GAP',1,'L03','Rotation-matrix time derivatives',95,'robotics-integration-author-L03-gap')
f=formula('Rdot=S(ω_A)R; S(ω_A)=Rdot Rᵀ',{'R':'rotation mapping body-frame vector components to fixed-frame A components','ω_A':'body angular velocity expressed in fixed frame A','S(ω_A)':'cross-product matrix satisfying S(ω_A)v=ω_A×v','Rdot':'time derivative of R'},{'R':'dimensionless','ω_A':'rad/s','S(ω_A),Rdot':'1/s'},['R is a differentiable proper rotation matrix.'])
b.add(104,'nonidentity-rotation-derivative','Derivative at a nonidentity orientation','R=[[0,-1,0],[1,0,0],[0,0,1]] maps body components to fixed-frame A components, and ω_A=(2,0,0) rad/s; which Rdot is correct?', ['[[0,0,0],[0,0,-2],[2,0,0]] s⁻¹','[[0,0,2],[0,0,0],[0,2,0]] s⁻¹','[[0,0,0],[0,0,-2],[0,2,0]] s⁻¹','[[0,0,0],[0,0,2],[-2,0,0]] s⁻¹'],0,'For fixed-frame angular-velocity components, multiply on the left: S(ω_A)R. The result is not generally skew-symmetric, even though S(ω_A)=Rdot Rᵀ is.', ['This is S(ω_A)R.','This is RS(ω_A), which uses the wrong side for fixed-frame ω_A.','This is S(ω_A) alone, omitting the nonidentity R.','This reverses the cross-product sign.'],typ='numerical',steps=['Construct S(ω_A)=[[0,0,0],[0,0,-2],[0,2,0]].','Multiply this matrix by R on the right.','The second row becomes (0,0,-2) and the third becomes (2,0,0).'],formulas=[f],assumptions=['Right-hand cross-product convention; R maps body coordinates into the fixed frame.'])
b.add(104,'rotation-derivative-frame','Which matrix must be skew-symmetric','For a differentiable proper rotation R from body frame B to fixed frame A, select all correct statements.', ['Rdot Rᵀ=S(ω_A) is skew-symmetric','Rᵀ Rdot=S(ω_B) is skew-symmetric','Rdot itself is skew-symmetric for every orientation','Rdot=S(ω_A)R=R S(ω_B), with ω_B=Rᵀω_A'],[0,1,3],'Differentiating RRᵀ=I and RᵀR=I gives the two skew matrices; their angular velocities are expressed in different frames. Rdot alone need not be skew.', ['Differentiating RRᵀ=I establishes the fixed-frame skew matrix.','Differentiating RᵀR=I establishes the body-frame skew matrix.','Only the products with R or Rᵀ are guaranteed skew; a nonidentity rotation supplies counterexamples.','Changing angular-velocity coordinates changes which side the skew matrix multiplies.'],typ='derivation',steps=['Differentiate RRᵀ=I to obtain Rdot Rᵀ+R Rdotᵀ=0.','Differentiate RᵀR=I to obtain RdotᵀR+RᵀRdot=0.','Use ω_B=Rᵀω_A and S(Rω_B)=R S(ω_B)Rᵀ.'],formulas=[f],assumptions=['The same physical angular velocity is expressed in A and B; R is a proper rotation.'])
b.save()
print('2 source-bound gap drafts saved.')
